declarations.cancelledNotification:
export interface CancelledNotification {
	requestId: JsonRpcId;
	reason?: string;
}

declarations.protectedResourceMetadata:
export interface OAuthProtectedResourceMetadata {
	resource: string;
	authorization_servers?: string[];
	scopes_supported?: string[];
	[key: string]: unknown;
}

declarations.authorizationServerMetadata:
export interface AuthorizationServerMetadata {
	issuer: string;
	authorization_endpoint: string;
	token_endpoint: string;
	registration_endpoint?: string;
	scopes_supported?: string[];
	response_types_supported: string[];
	grant_types_supported?: string[];
	token_endpoint_auth_methods_supported?: string[];
	code_challenge_methods_supported?: string[];
	client_id_metadata_document_supported?: boolean;
	/** Whether authorization responses carry an `iss` parameter (RFC 9207). */
	authorization_response_iss_parameter_supported?: boolean;
	[key: string]: unknown;
}

declarations.oauthState:
export interface McpOAuthState {
	serverUrl: string;
	clientInformation?: OAuthClientInformationMixed;
	tokens?: OAuthTokens;
	/** When the access token expires, in milliseconds since the epoch, from `expires_in` at the time it was saved. */
	tokensExpireAt?: number;
	codeVerifier?: string;
	oauthState?: string;
	discovery?: OAuthDiscoveryState;
}
